    ["Move out"] = "Ausziehen lassen",
    ["That companion is not available."] = "Dieser Begleiter ist nicht verfügbar.",
    ["Watson Northside"] = "Watson Northside",
    ["Westbrook Japantown"] = "Westbrook Japantown",
    ["You do not have that apartment."] = "Du hast diese Wohnung nicht.",
    ["at home"] = "zu Hause",
    ["out"] = "außer Haus",
    ["with you"] = "mit dir",
    ["{count} more housemates"] = "{count} weitere Mitbewohner",
    ["{name} has moved out."] = "{name} ist ausgezogen.",
    ["{name} is back at home."] = "{name} ist wieder zu Hause.",
